        (cpu, memory, "fallback".to_string(), "none".to_string())
    };

    Json(DashboardMetrics {
        active_connections,
        total_users,
        mail_queue: 0,
        mcp_services: 0,
        cpu,
        memory,
        network: 0.0,
        source,
        schema_version,
    })
}

