    Command::new("wg")
        .args(&["show", "wg0", "peers"])
        .output()
        .ok()
        .map(|output| {
            if output.status.success() {
                String::from_utf8_lossy(&output.stdout).lines().count()
            } else {
                0
            }
        })
        .unwrap_or(0)
